{
 "app_name": "todoist",
 "api_name": "show_projects",
 "path": "/todoist/projects",
 "method": "GET",
 "description": "Show or search a list of your projects.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from todoist app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query for projects.",
   "default": "",
   "constraints": []
  },
  {
   "name": "color",
   "type": "string",
   "required": false,
   "description": "The color of the project to filter by.",
   "default": null,
   "constraints": [
    "value in ['charcoal', 'red', 'blue', 'green', 'orange', 'yellow']"
   ]
  },
  {
   "name": "is_favorite",
   "type": "boolean",
   "required": false,
   "description": "Project's favorite status to filter by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "is_archived",
   "type": "boolean",
   "required": false,
   "description": "Project's archival status to filter by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 9223372036854775807"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the projects by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -created_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "name": "string",
    "color": "charcoal",
    "is_inbox": true,
    "description": "string",
    "is_favorite": true,
    "is_archived": true,
    "created_at": "2019-01-01T00:00:00",
    "project_id": 1,
    "creator": {
     "name": "string",
     "email": "user@example.com"
    },
    "num_tasks": 1,
    "sections": [
     {
      "id": 1,
      "name": "string",
      "num_tasks": 1
     }
    ],
    "collaborators": [
     {
      "name": "string",
      "email": "user@example.com"
     }
    ],
    "pending_invites": [
     {
      "invite_code": "string",
      "invitee": {
       "name": "string",
       "email": "user@example.com"
      },
      "inviter": {
       "name": "string",
       "email": "user@example.com"
      }
     }
    ],
    "is_shared": true
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "todoist",
 "api_name": "show_tasks",
 "path": "/todoist/projects/{project_id}/tasks",
 "method": "GET",
 "description": "Get a list of tasks within a project.",
 "parameters": [
  {
   "name": "project_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the project. You can use 0 for your Inbox project.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from todoist app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "section_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the section to filter tasks by. Set it to 0 for tasks without a section.",
   "default": null,
   "constraints": []
  },
  {
   "name": "assignee_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assignee to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "assigner_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assigner to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "priority",
   "type": "string",
   "required": false,
   "description": "The priority to filter tasks by.",
   "default": null,
   "constraints": [
    "value in ['high', 'medium', 'low']"
   ]
  },
  {
   "name": "is_completed",
   "type": "boolean",
   "required": false,
   "description": "Completion status to filter by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "due_today",
   "type": "boolean",
   "required": false,
   "description": "If true, only tasks due today will be returned. If false, all tasks will be returned.",
   "default": false,
   "constraints": []
  },
  {
   "name": "label_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the label to filter tasks by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "overdue",
   "type": "boolean",
   "required": false,
   "description": "If true, only tasks that are overdue will be returned. If false, all tasks will be returned.",
   "default": false,
   "constraints": []
  },
  {
   "name": "min_due_date",
   "type": "string",
   "required": false,
   "description": "Only tasks with a due date greater than or equal to this date will be returned. Date should be in YYYY-MM-DD format.",
   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_due_date",
   "type": "string",
   "required": false,
   "description": "Only tasks with a due date less than or equal to this date will be returned. Date should be in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the tasks by prefixed with +/- to reflect ascending/descending. Valid attributes: order_index, due_date and priority.",
   "default": "+order_index",
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "project_id": 1,
   "no_section_tasks": [
    {
     "order_index": 1,
     "task_id": 1,
     "title": "string",
     "description": "string",
     "num_sub_tasks": 1,
     "is_completed": true,
