    return all_comments

def parse_playlist_id_from_comment_text(text):
    m=re.search(r'/playlists/(\d+)', text or '')
    return int(m.group(1)) if m else None

def parse_add_remove_from_text(text):
    adds=[]
    removes=[]
    # normalize line breaks
    lines=(text or '').split('\n')
    for line in lines:
        line=line.strip()
        if not line:
            continue
        # Examples:
        # add => Title by Artist1, Artist2
        # remove => Title by Artist
        m=re.match(r'^(add|remove)\s*=>\s*(.+?)\s+by\s+(.+)$', line)
        if m:
            kind=m.group(1)
            title=m.group(2).strip()
            artists=[a.strip() for a in m.group(3).split(',') if a.strip()]
            entry={'title':title,'artists':artists}
            if kind=='add':
                adds.append(entry)
            else:
                removes.append(entry)
    return adds, removes

