        all_adds.extend(a)
        all_removes.extend(r)
    print('  parsed_adds',len(all_adds),'parsed_removes',len(all_removes))
    # de-duplicate by (title, set(artists lower))
    def norm(entry):
        return (entry['title'].strip().lower(), tuple(sorted([x.lower() for x in entry['artists']])) )
    dedup_adds=[]
    seen=set()
    for e in all_adds:
        k=norm(e)
        if k not in seen:
            seen.add(k)
            dedup_adds.append(e)
    dedup_removes=[]
    seen=set()
    for e in all_removes:
        k=norm(e)
        if k not in seen:
            seen.add(k)
            dedup_removes.append(e)
    print('  dedup_adds',len(dedup_adds),'dedup_removes',len(dedup_removes))
    ops_by_playlist[playlist_id]={
        'task_id':tid,
        'additions':dedup_adds,
        'removals':dedup_removes
    }

