def search_song_for_addition(title, artists):
    # Build queries to try
    artist0 = artists[0] if artists else ''
    query_candidates = []
    if artist0:
        query_candidates.append(f"{title} {artist0}")
    query_candidates.append(title)

    title_l = title.strip().lower()
    artist_set = {a.strip().lower() for a in (artists or []) if a.strip()}

    best=None
    for q in query_candidates:
        page_index=0
        page_limit=20
        results=[]
        while True:
            page = apis.spotify.search_songs(query=q, page_index=page_index, page_limit=page_limit)
            print('search query', q, 'page', page_index, 'len', 0 if not page else len(page))
            if not page:
                break
            results.extend(page)
            if len(page) < page_limit:
                break
            page_index += 1
        # candidates exact title
        candidates=[]
        for r in results:
            r_title = (r.get('title') or '').strip().lower()
            if r_title != title_l:
                continue
            r_artists = [a.get('name','').strip().lower() for a in (r.get('artists') or []) if a.get('name')]
            if artist_set:
                if any(a in r_artists for a in artist_set):
                    candidates.append(r)
            else:
                candidates.append(r)
        if candidates:
            best=candidates[0]
            print('  best exact match for', title, 'using query', q, 'song_id', best['song_id'])
            break
        # fallback: substring title
        for r in results:
            if title_l in (r.get('title') or '').strip().lower():
                best=r
                print('  best substring match for', title, 'using query', q, 'song_id', best['song_id'])
                break
        if best:
            break
    return best

